void Solver::bump_var(int var, double coeff) {
    if (coeff == 0.0) return;                     // nothing to do

    // increase activity of the variable
    double delta = var_inc * coeff;
    activity[var] += delta;

    // overflow protection: if any activity becomes too large, rescale all
    const double ACT_LIMIT = 1e100;
    const double RESCALE   = 1e-100;
    if (activity[var] > ACT_LIMIT) {
        for (int i = 1; i <= vars; ++i) activity[i] *= RESCALE;
        var_inc *= RESCALE;
    }

    // keep the VSIDS heap up‑to‑date
    if (vsids.inHeap(var)) vsids.update(var);
}
